import React, { useState, useEffect, useRef } from 'react';
import { Github, Linkedin, Mail, Phone, ExternalLink, Award, Briefcase, GraduationCap, Code, Database, Cloud, Brain, ChevronDown, Download, Menu, X, ArrowRight, Sparkles, Zap, Target } from 'lucide-react';

const Portfolio = () => {
  const [scrollY, setScrollY] = useState(0);
  const [activeSection, setActiveSection] = useState('hero');
  const [menuOpen, setMenuOpen] = useState(false);
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [isVisible, setIsVisible] = useState({});
  const [typedText, setTypedText] = useState('');
  const fullText = "AI & Machine Learning Engineer";

  useEffect(() => {
    const handleScroll = () => {
      setScrollY(window.scrollY);
      
      // Detect active section
      const sections = ['hero', 'about', 'experience', 'projects', 'skills', 'contact'];
      const current = sections.find(section => {
        const element = document.getElementById(section);
        if (element) {
          const rect = element.getBoundingClientRect();
          return rect.top <= 100 && rect.bottom >= 100;
        }
        return false;
      });
      if (current) setActiveSection(current);
    };

    const handleMouseMove = (e) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    window.addEventListener('scroll', handleScroll);
    window.addEventListener('mousemove', handleMouseMove);
    
    return () => {
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  // Typing animation
  useEffect(() => {
    if (typedText.length < fullText.length) {
      setTimeout(() => {
        setTypedText(fullText.slice(0, typedText.length + 1));
      }, 100);
    }
  }, [typedText]);

  // Intersection Observer for animations
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          setIsVisible(prev => ({
            ...prev,
            [entry.target.id]: entry.isIntersecting
          }));
        });
      },
      { threshold: 0.1 }
    );

    document.querySelectorAll('[data-animate]').forEach((el) => {
      observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

  const projects = [
    {
      title: "Deep Farming",
      subtitle: "Crop Disease Surveillance with Deep Learning",
      description: "Smart farming solution using CNN models for crop disease detection with real-time predictions via Flask web app. Achieved 95%+ accuracy in disease classification.",
      tags: ["Python", "TensorFlow", "CNN", "Flask", "Computer Vision"],
      icon: "🌱",
      gradient: "from-green-500 to-emerald-600",
      metrics: { accuracy: "95%", models: "3", dataset: "50K+" }
    },
    {
      title: "Intelligent SQL-Gen",
      subtitle: "NLP to SQL via RAG Architecture",
      description: "Automated pipelines with vector-based retrieval for semantic schema-linking and accurate SQL generation from natural language. Reduced query time by 80%.",
      tags: ["Azure OpenAI", "LangChain", "FAISS", "Streamlit", "RAG"],
      icon: "💬",
      gradient: "from-blue-500 to-cyan-600",
      metrics: { accuracy: "92%", queries: "1000+", time: "-80%" }
    },
    {
      title: "HealthCare Guidance Navigator",
      subtitle: "Agentic AI for Clinical Guidance",
      description: "RAG-based healthcare chatbot with intelligent retrieval pipelines providing real-time clinical insights and decision support for medical professionals.",
      tags: ["Agentic AI", "ChromaDB", "LangGraph", "Azure OpenAI"],
      icon: "🏥",
      gradient: "from-pink-500 to-rose-600",
      metrics: { users: "500+", accuracy: "94%", queries: "5K+" }
    }
  ];

  const skills = [
    {
      category: "Machine Learning",
      items: ["Linear/Logistic Regression", "Random Forest", "Decision Trees", "K-means", "Gradient Boosting", "XGBoost"],
      icon: <Brain className="w-6 h-6" />,
      color: "purple"
    },
    {
      category: "Generative AI",
      items: ["RAG", "Prompt Engineering", "GPT/Claude/Gemini", "Vector DBs", "Fine-tuning", "Embeddings"],
      icon: <Sparkles className="w-6 h-6" />,
      color: "pink"
    },
    {
      category: "Cloud & DevOps",
      items: ["AWS (EC2, Lambda, SageMaker)", "Azure OpenAI", "Flask", "Docker", "Git", "CI/CD"],
      icon: <Cloud className="w-6 h-6" />,
      color: "blue"
    },
    {
      category: "Data & Databases",
      items: ["SQL", "Pandas", "NumPy", "Scikit-learn", "FAISS", "ChromaDB"],
      icon: <Database className="w-6 h-6" />,
      color: "cyan"
    },
    {
      category: "Deep Learning",
      items: ["TensorFlow", "PyTorch", "CNN", "RNN", "Transformers", "BERT"],
      icon: <Zap className="w-6 h-6" />,
      color: "yellow"
    },
    {
      category: "Agentic AI",
      items: ["LangChain", "LangGraph", "CrewAI", "AutoGen", "Multi-agent Systems"],
      icon: <Target className="w-6 h-6" />,
      color: "green"
    }
  ];

  const experience = {
    company: "Vcitysoft Pvt.Ltd",
    role: "AI & ML Intern",
    duration: "6 Months",
    highlights: [
      "Developed end-to-end AI solutions across financial and healthcare domains",
      "Built scalable Python applications using Flask and OOP principles",
      "Implemented data visualization and statistical analysis pipelines",
      "Collaborated with cross-functional teams for seamless integration",
      "Utilized AWS and Azure cloud platforms for deployment"
    ]
  };

  const stats = [
    { label: "Projects Completed", value: "15+", icon: "🚀" },
    { label: "ML Models Deployed", value: "8+", icon: "🤖" },
    { label: "Lines of Code", value: "50K+", icon: "💻" },
    { label: "Certifications", value: "5+", icon: "🏆" }
  ];

  return (
    <div className="bg-black text-white min-h-screen overflow-x-hidden">
      {/* Custom Cursor */}
      <div 
        className="fixed w-6 h-6 border-2 border-purple-500 rounded-full pointer-events-none z-50 mix-blend-difference transition-transform duration-100"
        style={{ 
          left: `${mousePosition.x}px`, 
          top: `${mousePosition.y}px`,
          transform: 'translate(-50%, -50%)'
        }}
      />

      {/* Animated Background */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div 
          className="absolute w-96 h-96 bg-purple-600 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-blob"
          style={{ top: '10%', left: '10%', animationDelay: '0s' }}
        />
        <div 
          className="absolute w-96 h-96 bg-blue-600 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-blob"
          style={{ top: '50%', right: '10%', animationDelay: '2s' }}
        />
        <div 
          className="absolute w-96 h-96 bg-pink-600 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-blob"
          style={{ bottom: '10%', left: '30%', animationDelay: '4s' }}
        />
      </div>

      {/* Navigation */}
      <nav className="fixed top-0 w-full z-50 backdrop-blur-xl bg-black/50 border-b border-white/10">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <div className="text-2xl font-bold">
            <span className="bg-gradient-to-r from-purple-400 via-pink-400 to-blue-400 bg-clip-text text-transparent">
              RH
            </span>
          </div>
          
          {/* Desktop Menu */}
          <div className="hidden md:flex gap-8 items-center">
            {['About', 'Experience', 'Projects', 'Skills', 'Contact'].map((item) => (
              <a 
                key={item}
                href={`#${item.toLowerCase()}`}
                className={`relative hover:text-purple-400 transition-colors ${
                  activeSection === item.toLowerCase() ? 'text-purple-400' : ''
                }`}
              >
                {item}
                {activeSection === item.toLowerCase() && (
                  <span className="absolute -bottom-1 left-0 w-full h-0.5 bg-gradient-to-r from-purple-400 to-blue-400"></span>
                )}
              </a>
            ))}
            <a 
              href="#contact"
              className="px-6 py-2 bg-gradient-to-r from-purple-600 to-blue-600 rounded-full hover:scale-105 transition-transform"
            >
              Hire Me
            </a>
          </div>

          {/* Mobile Menu Button */}
          <button 
            className="md:hidden"
            onClick={() => setMenuOpen(!menuOpen)}
          >
            {menuOpen ? <X /> : <Menu />}
          </button>
        </div>

        {/* Mobile Menu */}
        {menuOpen && (
          <div className="md:hidden absolute top-full left-0 w-full backdrop-blur-xl bg-black/90 border-b border-white/10 py-6">
            <div className="flex flex-col gap-4 px-6">
              {['About', 'Experience', 'Projects', 'Skills', 'Contact'].map((item) => (
                <a 
                  key={item}
                  href={`#${item.toLowerCase()}`}
                  className="hover:text-purple-400 transition-colors"
                  onClick={() => setMenuOpen(false)}
                >
                  {item}
                </a>
              ))}
            </div>
          </div>
        )}
      </nav>

      {/* Hero Section */}
      <section id="hero" className="relative min-h-screen flex items-center justify-center px-6 pt-20">
        {/* AI/Data Science Background Pattern */}
        <div className="absolute inset-0 opacity-5">
          <svg className="w-full h-full" xmlns="http://www.w3.org/2000/svg">
            <defs>
              <pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse">
                <path d="M 50 0 L 0 0 0 50" fill="none" stroke="rgba(139, 92, 246, 0.3)" strokeWidth="1"/>
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
          </svg>
          {/* Floating Tech Icons */}
          <div className="absolute top-20 left-10 text-6xl animate-float">🤖</div>
          <div className="absolute top-40 right-20 text-5xl animate-float" style={{animationDelay: '1s'}}>📊</div>
          <div className="absolute bottom-40 left-20 text-5xl animate-float" style={{animationDelay: '2s'}}>🧠</div>
          <div className="absolute bottom-20 right-40 text-6xl animate-float" style={{animationDelay: '0.5s'}}>💻</div>
        </div>
        
        <div className="max-w-7xl mx-auto z-10 w-full">
          <div 
            className="transform transition-all duration-1000 flex flex-col md:flex-row items-center justify-center gap-12 md:gap-16"
            style={{ 
              opacity: Math.max(0, 1 - scrollY / 500),
              transform: `translateY(${scrollY * 0.3}px)`
            }}
          >
            {/* Profile Picture with 3D effect */}
            <div className="flex-shrink-0">
              <div className="relative group cursor-pointer">
                <div className="absolute -inset-2 bg-gradient-to-r from-purple-600 via-pink-600 to-blue-600 rounded-full blur-2xl opacity-75 group-hover:opacity-100 transition duration-1000 animate-pulse"></div>
                <div className="absolute -inset-1 bg-gradient-to-r from-purple-400 via-pink-400 to-blue-400 rounded-full blur-lg opacity-50 group-hover:opacity-75 transition duration-500 animate-spin-slow"></div>
                <img 
                  src="/profile.jpeg"
                  alt="Rohit Harne"
                  className="relative w-64 h-64 md:w-80 md:h-80 rounded-full object-cover border-4 border-black shadow-2xl group-hover:scale-105 transition-transform duration-500"
                />
                <div className="absolute bottom-6 right-6 w-8 h-8 bg-green-500 rounded-full border-4 border-black animate-pulse"></div>
              </div>
            </div>

            {/* Content */}
            <div className="flex-1 text-center md:text-left max-w-2xl">
              <h1 className="text-5xl md:text-7xl lg:text-8xl font-black mb-4 leading-tight">
                <span className="bg-gradient-to-r from-purple-400 via-pink-400 to-blue-400 bg-clip-text text-transparent animate-gradient">
                  ROHIT HARNE
                </span>
              </h1>
              
              <div className="h-10 md:h-12 mb-6">
                <p className="text-xl md:text-3xl font-semibold text-transparent bg-clip-text bg-gradient-to-r from-gray-200 to-gray-400">
                  {typedText}
                  <span className="animate-blink">|</span>
                </p>
              </div>
              
              <p className="text-base md:text-lg text-gray-400 mb-8 leading-relaxed">
                Crafting intelligent AI systems with <span className="text-purple-400 font-semibold">Deep Learning</span>, 
                <span className="text-pink-400 font-semibold"> Generative AI</span>, and 
                <span className="text-blue-400 font-semibold"> Agentic Workflows</span>. 
                Specialized in RAG architectures and production-ready ML solutions.
              </p>
            
                          
              {/* CTA Buttons */}
              <div className="flex gap-4 justify-center md:justify-start items-center flex-wrap mb-8">
                <a 
                  href="#projects"
                  className="group flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-purple-600 to-blue-600 rounded-full hover:scale-105 hover:shadow-2xl hover:shadow-purple-500/50 transition-all duration-300 font-semibold text-sm md:text-base"
                >
                  View My Work
                  <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                </a>
                <a 
                  href="mailto:rohitharne21@gmail.com"
                  className="flex items-center gap-2 px-6 py-3 border-2 border-white/20 rounded-full hover:bg-white/10 hover:border-purple-500/50 transition-all duration-300 font-semibold text-sm md:text-base"
                >
                  <Mail className="w-4 h-4" />
                  Get In Touch
                </a>
                <a 
                  href="#"
                  className="flex items-center gap-2 px-6 py-3 border-2 border-white/20 rounded-full hover:bg-white/10 hover:border-blue-500/50 transition-all duration-300 font-semibold text-sm md:text-base"
                >
                  <Download className="w-4 h-4" />
                  Download CV
                </a>
              </div>

              {/* Social Links */}
              <div className="flex gap-4 justify-center md:justify-start">
                <a 
                  href="https://github.com/rohitharne" 
                  target="_blank"
                  rel="noopener noreferrer"
                  className="w-12 h-12 flex items-center justify-center rounded-full border border-white/20 hover:border-purple-500/50 hover:bg-white/5 transition-all hover:scale-110"
                >
                  <Github className="w-5 h-5" />
                </a>
                <a 
                  href="https://linkedin.com/in/rohitharne" 
                  target="_blank"
                  rel="noopener noreferrer"
                  className="w-12 h-12 flex items-center justify-center rounded-full border border-white/20 hover:border-blue-500/50 hover:bg-white/5 transition-all hover:scale-110"
                >
                  <Linkedin className="w-5 h-5" />
                </a>
                <a 
                  href="mailto:rohitharne21@gmail.com"
                  className="w-12 h-12 flex items-center justify-center rounded-full border border-white/20 hover:border-pink-500/50 hover:bg-white/5 transition-all hover:scale-110"
                >
                  <Mail className="w-5 h-5" />
                </a>
                <a 
                  href="tel:9309569137"
                  className="w-12 h-12 flex items-center justify-center rounded-full border border-white/20 hover:border-green-500/50 hover:bg-white/5 transition-all hover:scale-110"
                >
                  <Phone className="w-5 h-5" />
                </a>
              </div>
            </div>
          </div>
        </div>
        
        {/* Scroll Indicator */}
        <a 
          href="#about"
          className="absolute bottom-10 left-1/2 transform -translate-x-1/2 animate-bounce cursor-pointer"
        >
          <div className="w-8 h-12 border-2 border-white/30 rounded-full flex justify-center p-2">
            <ChevronDown className="w-4 h-4 animate-pulse" />
          </div>
        </a>
      </section>

      {/* Experience Section */}
      <section id="about" className="relative py-32 px-6 bg-gradient-to-b from-black via-purple-950/10 to-black">
        <div className="max-w-6xl mx-auto">
          <div 
            data-animate
            id="exp-title"
            className={`text-center mb-20 transform transition-all duration-1000 ${
              isVisible['exp-title'] ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
            }`}
          >
            <h2 className="text-5xl md:text-6xl font-bold mb-4">
              <span className="bg-gradient-to-r from-purple-400 to-blue-400 bg-clip-text text-transparent">
                Experience
              </span>
            </h2>
          </div>
          
          <div 
            data-animate
            id="exp-card"
            className={`backdrop-blur-lg bg-gradient-to-br from-purple-900/20 via-pink-900/10 to-blue-900/20 rounded-3xl p-10 border border-purple-500/30 hover:border-purple-500/60 transition-all duration-500 transform ${
              isVisible['exp-card'] ? 'opacity-100 scale-100' : 'opacity-0 scale-95'
            }`}
          >
            <div className="flex items-start gap-6 mb-8">
              <div className="w-16 h-16 bg-gradient-to-br from-purple-500 to-blue-500 rounded-2xl flex items-center justify-center flex-shrink-0">
                <Briefcase className="w-8 h-8" />
              </div>
              <div className="flex-1">
                <h3 className="text-3xl font-bold mb-2">{experience.role}</h3>
                <p className="text-xl text-purple-300 mb-2">{experience.company}</p>
                <p className="text-gray-400">{experience.duration}</p>
              </div>
            </div>
            
            <div className="space-y-4">
              {experience.highlights.map((highlight, idx) => (
                <div 
                  key={idx}
                  className="flex items-start gap-4 p-4 rounded-xl hover:bg-white/5 transition-all group"
                >
                  <div className="w-2 h-2 bg-purple-400 rounded-full mt-2 group-hover:scale-150 transition-transform"></div>
                  <p className="text-gray-300 group-hover:text-white transition-colors">{highlight}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Projects Section */}
      <section id="projects" className="relative py-32 px-6">
        <div className="max-w-7xl mx-auto">
          <div 
            data-animate
            id="projects-title"
            className={`text-center mb-20 transform transition-all duration-1000 ${
              isVisible['projects-title'] ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
            }`}
          >
            <h2 className="text-5xl md:text-6xl font-bold mb-4">
              <span className="bg-gradient-to-r from-purple-400 to-blue-400 bg-clip-text text-transparent">
                Featured Projects
              </span>
            </h2>
            <p className="text-gray-400 text-lg">
              Building the future with AI and Machine Learning
            </p>
          </div>
          
          <div className="grid lg:grid-cols-1 gap-8">
            {projects.map((project, idx) => (
              <div 
                key={idx}
                data-animate
                id={`project-${idx}`}
                className={`group backdrop-blur-lg bg-gradient-to-br from-white/5 to-transparent rounded-3xl p-8 border border-white/10 hover:border-purple-500/50 transition-all duration-500 cursor-pointer hover:scale-[1.02] transform ${
                  isVisible[`project-${idx}`] ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
                }`}
                style={{ transitionDelay: `${idx * 150}ms` }}
              >
                <div className="flex flex-col md:flex-row items-start gap-8">
                  <div className={`w-24 h-24 bg-gradient-to-br ${project.gradient} rounded-2xl flex items-center justify-center text-5xl flex-shrink-0 group-hover:scale-110 group-hover:rotate-6 transition-transform duration-500`}>
                    {project.icon}
                  </div>
                  
                  <div className="flex-1">
                    <h3 className="text-3xl font-bold mb-2 group-hover:text-transparent group-hover:bg-clip-text group-hover:bg-gradient-to-r group-hover:from-purple-400 group-hover:to-blue-400 transition-all">
                      {project.title}
                    </h3>
                    <p className="text-lg text-gray-400 mb-4">{project.subtitle}</p>
                    <p className="text-gray-300 mb-6 leading-relaxed">{project.description}</p>
                    
                    {/* Metrics */}
                    <div className="flex gap-6 mb-6">
                      {Object.entries(project.metrics).map(([key, value]) => (
                        <div key={key} className="text-center">
                          <div className={`text-2xl font-bold bg-gradient-to-r ${project.gradient} bg-clip-text text-transparent`}>
                            {value}
                          </div>
                          <div className="text-xs text-gray-500 uppercase">{key}</div>
                        </div>
                      ))}
                    </div>
                    
                    {/* Tags */}
                    <div className="flex flex-wrap gap-2">
                      {project.tags.map((tag, i) => (
                        <span 
                          key={i}
                          className={`px-4 py-2 bg-gradient-to-r ${project.gradient} bg-opacity-10 border border-white/20 rounded-full text-sm hover:scale-105 transition-transform`}
                        >
                          {tag}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Skills Section */}
      <section id="skills" className="relative py-32 px-6 bg-gradient-to-b from-black via-blue-950/10 to-black">
        <div className="max-w-7xl mx-auto">
          <div 
            data-animate
            id="skills-title"
            className={`text-center mb-20 transform transition-all duration-1000 ${
              isVisible['skills-title'] ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
            }`}
          >
            <h2 className="text-5xl md:text-6xl font-bold mb-4">
              <span className="bg-gradient-to-r from-purple-400 to-blue-400 bg-clip-text text-transparent">
                Skills & Expertise
              </span>
            </h2>
            <p className="text-gray-400 text-lg">
              Comprehensive toolkit for building intelligent systems
            </p>
          </div>
          
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
            {skills.map((skill, idx) => (
              <div 
                key={idx}
                data-animate
                id={`skill-${idx}`}
                className={`group backdrop-blur-lg bg-gradient-to-br from-white/5 to-transparent rounded-2xl p-6 border border-white/10 hover:border-${skill.color}-500/50 transition-all duration-500 cursor-pointer hover:scale-105 transform ${
                  isVisible[`skill-${idx}`] ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
                }`}
                style={{ transitionDelay: `${idx * 100}ms` }}
              >
                <div className="flex items-center gap-4 mb-6">
                  <div className={`text-${skill.color}-400 group-hover:scale-125 transition-transform`}>
                    {skill.icon}
                  </div>
                  <h3 className="text-xl font-bold group-hover:text-transparent group-hover:bg-clip-text group-hover:bg-gradient-to-r group-hover:from-purple-400 group-hover:to-blue-400 transition-all">
                    {skill.category}
                  </h3>
                </div>
                <div className="flex flex-wrap gap-2">
                  {skill.items.map((item, i) => (
                    <span 
                      key={i}
                      className="px-3 py-1 bg-white/5 border border-white/10 rounded-lg text-xs hover:bg-white/10 transition-colors"
                    >
                      {item}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Contact Section */}
      <section id="contact" className="relative py-32 px-6">
        <div className="max-w-4xl mx-auto text-center">
          <div 
            data-animate
            id="contact-content"
            className={`transform transition-all duration-1000 ${
              isVisible['contact-content'] ? 'opacity-100 scale-100' : 'opacity-0 scale-95'
            }`}
          >
            <h2 className="text-5xl md:text-6xl font-bold mb-6">
              <span className="bg-gradient-to-r from-purple-400 to-blue-400 bg-clip-text text-transparent">
                Let's Build Something Amazing
              </span>
            </h2>
            <p className="text-xl text-gray-300 mb-12 leading-relaxed">
              I'm always excited to discuss new projects, innovative ideas, or opportunities to be part of your vision. 
              Let's connect and create something extraordinary together!
            </p>
            
            <div className="flex flex-wrap gap-6 justify-center mb-12">
              <a 
                href="mailto:rohitharne21@gmail.com"
                className="group flex items-center gap-3 px-8 py-5 backdrop-blur-lg bg-gradient-to-r from-purple-600/20 to-blue-600/20 rounded-2xl border border-purple-500/30 hover:border-purple-500/70 hover:scale-105 transition-all duration-300"
              >
                <Mail className="w-6 h-6 group-hover:rotate-12 transition-transform" />
                <div className="text-left">
                  <div className="text-xs text-gray-400">Email</div>
                  <div className="font-semibold">rohitharne21@gmail.com</div>
                </div>
              </a>
              <a 
                href="tel:9309569137"
                className="group flex items-center gap-3 px-8 py-5 backdrop-blur-lg bg-gradient-to-r from-blue-600/20 to-cyan-600/20 rounded-2xl border border-blue-500/30 hover:border-blue-500/70 hover:scale-105 transition-all duration-300"
              >
                <Phone className="w-6 h-6 group-hover:rotate-12 transition-transform" />
                <div className="text-left">
                  <div className="text-xs text-gray-400">Phone</div>
                  <div className="font-semibold">+91 9309569137</div>
                </div>
              </a>
            </div>

            <div className="flex gap-4 justify-center">
              <a 
                href="https://github.com/rohitharne" 
                target="_blank"
                rel="noopener noreferrer"
                className="w-14 h-14 flex items-center justify-center rounded-2xl bg-white/5 border border-white/10 hover:border-purple-500/50 hover:bg-white/10 transition-all hover:scale-110 hover:-translate-y-1"
              >
                <Github className="w-6 h-6" />
              </a>
              <a 
                href="https://linkedin.com/in/rohitharne" 
                target="_blank"
                rel="noopener noreferrer"
                className="w-14 h-14 flex items-center justify-center rounded-2xl bg-white/5 border border-white/10 hover:border-blue-500/50 hover:bg-white/10 transition-all hover:scale-110 hover:-translate-y-1"
              >
                <Linkedin className="w-6 h-6" />
              </a>
              <a 
                href="https://portavia.framer.website/" 
                target="_blank"
                rel="noopener noreferrer"
                className="w-14 h-14 flex items-center justify-center rounded-2xl bg-white/5 border border-white/10 hover:border-pink-500/50 hover:bg-white/10 transition-all hover:scale-110 hover:-translate-y-1"
              >
                <ExternalLink className="w-6 h-6" />
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="relative py-12 px-6 border-t border-white/10">
        <div className="max-w-6xl mx-auto">
          <div className="flex flex-col md:flex-row justify-between items-center gap-6">
            <div>
              <p className="text-gray-400">
                © 2024 Rohit Harne. Crafted with 💜 using React & Tailwind CSS
              </p>
              <p className="text-gray-500 text-sm mt-1">
                Gurudev Nagar Dabki Road, Akola, Maharashtra
              </p>
            </div>
            <div className="flex gap-4">
              <a href="#hero" className="text-gray-400 hover:text-purple-400 transition-colors">Back to Top ↑</a>
            </div>
          </div>
        </div>
      </footer>

      <style>{`
        @keyframes gradient {
          0%, 100% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
        }
        
        .animate-gradient {
          background-size: 200% 200%;
          animation: gradient 3s ease infinite;
        }
        
        @keyframes blob {
          0%, 100% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(20px, -50px) scale(1.1); }
          50% { transform: translate(-20px, 20px) scale(0.9); }
          75% { transform: translate(50px, 50px) scale(1.05); }
        }
        
        .animate-blob {
          animation: blob 7s infinite;
        }

        @keyframes float {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-20px); }
        }
        
        .animate-float {
          animation: float 6s ease-in-out infinite;
        }

        @keyframes blink {
          0%, 100% { opacity: 1; }
          50% { opacity: 0; }
        }
        
        .animate-blink {
          animation: blink 1s infinite;
        }

        @keyframes spin-slow {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        
        .animate-spin-slow {
          animation: spin-slow 8s linear infinite;
        }
      `}</style>
    </div>
  );
};

export default Portfolio;
